  7	import com.pousada.repo.ReservationRepository;
  8	import com.pousada.repo.RoomRepository;
  9	import com.pousada.repo.MessageRepository;
 10	import com.pousada.service.ReservationService;
 11	import com.pousada.util.Database;
 12	import io.javalin.Javalin;
 13	import org.json.JSONObject;
 14	
 15	public class Application {
 16	    public static void main(String[] args) throws Exception {
 17	        String dbUrl = System.getenv("DB_URL");
 18	        String dbUser = System.getenv("DB_USER");
 19	        String dbPassword = System.getenv("DB_PASSWORD");
 20	        String portStr = System.getenv("PORT");
 21	
 22	        if (dbUrl == null || dbUser == null || dbPassword == null) {
 23	            throw new RuntimeException("Database environment variables (DB_URL, DB_USER, DB_PASSWORD) are required");
 24	        }
 25	
 26	        int port = portStr != null ? Integer.parseInt(portStr) : 7070;
 27	
 28	        Database.init(dbUrl, dbUser, dbPassword);
 29	
 30	        RoomRepository roomRepo = new RoomRepository();
 31	        roomRepo.initializeRooms();
 32	
 33	        ReservationRepository reservationRepo = new ReservationRepository();
 34	        MessageRepository messageRepo = new MessageRepository();
 35	        ReservationService reservationService = new ReservationService(reservationRepo, roomRepo, messageRepo);
 36	
 37	        Javalin app = Javalin.create()
 38	            .exception(Exception.class, (e, ctx) -> {
 39	                e.printStackTrace();
 40	                ctx.json(new JSONObject()
 41	                    .put("error", "INTERNAL_ERROR")
 42	                    .put("message", e.getMessage())
 43	                    .toString());
 44	                ctx.status(500);
 45	            });
 46	
 47	        RoomRoutes.register(app, roomRepo);
 48	        ReservationRoutes.register(app, reservationService, reservationRepo);
 49	        MessageRoutes.register(app, messageRepo);
 50	        ReportRoutes.register(app, reservationRepo, roomRepo);
 51	
 52	        app.start(port);
 53	        System.out.println("Application started on port " + port);
 54	    }
 55	}
 56	package com.pousada.api;
 57	
 58	import com.pousada.domain.RatePlan;
 59	import com.pousada.domain.Reservation;
 60	import com.pousada.domain.Room;
