 71	public class ReservationRoutes {
 72	    private static RoomRepository roomRepo;
 73	
 74	    public static void register(Javalin app, ReservationService reservationService, ReservationRepository reservationRepo) {
 75	        app.post("/reservations", ctx -> {
 76	            try {
 77	                String body = ctx.body();
 78	                if (body == null || body.isEmpty()) {
 79	                    ctx.status(400);
 80	                    ctx.json(new JSONObject()
 81	                        .put("error", "INVALID_REQUEST")
 82	                        .put("message", "Request body is required")
 83	                        .toString());
 84	                    return;
 85	                }
 86	
 87	                JSONObject json = new JSONObject(body);
 88	
 89	                if (!json.has("roomNumber") || !json.has("guestName") || !json.has("guestEmail") || !json.has("guestCpf") ||
 90	                    !json.has("checkIn") || !json.has("checkOut") || !json.has("guests") || !json.has("ratePlan")) {
 91	                    ctx.status(400);
 92	                    ctx.json(new JSONObject()
 93	                        .put("error", "INVALID_REQUEST")
 94	                        .put("message", "Missing required fields")
 95	                        .toString());
 96	                    return;
 97	                }
 98	
 99	                int roomNumber = json.getInt("roomNumber");
100	                String guestName = json.getString("guestName");
101	                String guestEmail = json.getString("guestEmail");
102	                String guestCpf = json.getString("guestCpf");
103	                LocalDate checkIn = LocalDate.parse(json.getString("checkIn"));
104	                LocalDate checkOut = LocalDate.parse(json.getString("checkOut"));
105	                int guests = json.getInt("guests");
106	                RatePlan ratePlan = RatePlan.valueOf(json.getString("ratePlan"));
107	
108	                Reservation reservation = reservationService.createReservation(roomNumber, guestName, guestEmail, guestCpf,
109	                    checkIn, checkOut, guests, ratePlan);
110	
111	                ctx.status(201);
112	                ctx.json(reservationToJson(reservation).toString());
113	            } catch (ValidationException e) {
114	                int status = getStatusForError(e.getErrorCode());
115	                ctx.status(status);
116	                ctx.json(new JSONObject()
117	                    .put("error", e.getErrorCode())
118	                    .put("message", e.getMessage())
119	                    .toString());
120	            } catch (Exception e) {
121	                ctx.status(400);
122	                ctx.json(new JSONObject()
123	                    .put("error", "INVALID_REQUEST")
124	                    .put("message", "Invalid request: " + e.getMessage())
125	                    .toString());
126	            }
127	        });
128	
129	        app.get("/reservations/{id}", ctx -> {
130	            try {
131	                int id = Integer.parseInt(ctx.pathParam("id"));
132	                Reservation reservation = reservationService.getReservation(id);
133	                ctx.json(reservationToJson(reservation).toString());
134	            } catch (ValidationException e) {
135	                ctx.status(404);
136	                ctx.json(new JSONObject()
137	                    .put("error", e.getErrorCode())
138	                    .put("message", e.getMessage())
139	                    .toString());
140	            } catch (Exception e) {
141	                ctx.status(500);
142	                ctx.json(new JSONObject()
143	                    .put("error", "INTERNAL_ERROR")
144	                    .put("message", e.getMessage())
145	                    .toString());
146	            }
147	        });
148	
149	        app.post("/reservations/{id}/confirmation", ctx -> {
150	            try {
151	                int id = Integer.parseInt(ctx.pathParam("id"));
152	                String body = ctx.body();
153	                JSONObject json = new JSONObject(body);
154	                BigDecimal amountPaid = json.getBigDecimal("amountPaid");
155	
156	                Reservation reservation = reservationService.confirmReservation(id, amountPaid);
157	                ctx.json(reservationToJson(reservation).toString());
158	            } catch (ValidationException e) {
159	                int status = getStatusForError(e.getErrorCode());
160	                ctx.status(status);
161	                ctx.json(new JSONObject()
162	                    .put("error", e.getErrorCode())
163	                    .put("message", e.getMessage())
164	                    .toString());
165	            } catch (Exception e) {
166	                ctx.status(400);
167	                ctx.json(new JSONObject()
168	                    .put("error", "INVALID_REQUEST")
169	                    .put("message", "Invalid request: " + e.getMessage())
170	                    .toString());
171	            }
172	        });
173	
174	        app.post("/reservations/{id}/cancellation", ctx -> {
175	            try {
176	                int id = Integer.parseInt(ctx.pathParam("id"));
177	                Reservation reservation = reservationService.cancelReservation(id);
178	                ctx.json(reservationToJson(reservation).toString());
179	            } catch (ValidationException e) {
180	                int status = getStatusForError(e.getErrorCode());
181	                ctx.status(status);
182	                ctx.json(new JSONObject()
183	                    .put("error", e.getErrorCode())
184	                    .put("message", e.getMessage())
185	                    .toString());
186	            } catch (Exception e) {
187	                ctx.status(500);
188	                ctx.json(new JSONObject()
189	                    .put("error", "INTERNAL_ERROR")
190	                    .put("message", e.getMessage())
191	                    .toString());
192	            }
193	        });
194	
195	        app.post("/reservations/{id}/check-in", ctx -> {
196	            try {
197	                int id = Integer.parseInt(ctx.pathParam("id"));
198	                Reservation reservation = reservationService.checkIn(id);
199	                ctx.json(reservationToJson(reservation).toString());
200	            } catch (ValidationException e) {
201	                int status = getStatusForError(e.getErrorCode());
202	                ctx.status(status);
203	                ctx.json(new JSONObject()
204	                    .put("error", e.getErrorCode())
205	                    .put("message", e.getMessage())
206	                    .toString());
207	            } catch (Exception e) {
208	                ctx.status(500);
209	                ctx.json(new JSONObject()
210	                    .put("error", "INTERNAL_ERROR")
211	                    .put("message", e.getMessage())
212	                    .toString());
213	            }
214	        });
215	
216	        app.post("/reservations/{id}/check-out", ctx -> {
217	            try {
218	                int id = Integer.parseInt(ctx.pathParam("id"));
219	                Reservation reservation = reservationService.checkOut(id);
220	
221	                Room room = getRoomRepository().findByNumber(reservation.getRoomNumber());
222	                String receipt = reservationService.buildReceipt(reservation, room);
223	
224	                JSONObject receiptJson = new JSONObject()
225	                    .put("title", "Comprovante de reserva")
226	                    .put("reservationId", reservation.getId())
227	                    .put("guestName", reservation.getGuestName())
228	                    .put("guestCpf", reservation.getGuestCpf())
229	                    .put("roomNumber", reservation.getRoomNumber())
230	                    .put("roomType", room.getType().getDisplayName())
231	                    .put("checkIn", reservation.getCheckIn().toString())
232	                    .put("checkOut", reservation.getCheckOut().toString())
233	                    .put("nights", reservation.getNights())
234	                    .put("subtotal", reservation.getSubtotal().doubleValue())
235	                    .put("discount", reservation.getDiscount().doubleValue())
236	                    .put("total", reservation.getTotal().doubleValue());
237	
238	                ctx.json(receiptJson.toString());
239	            } catch (ValidationException e) {
240	                int status = getStatusForError(e.getErrorCode());
241	                ctx.status(status);
242	                ctx.json(new JSONObject()
243	                    .put("error", e.getErrorCode())
244	                    .put("message", e.getMessage())
245	                    .toString());
246	            } catch (Exception e) {
247	                ctx.status(500);
248	                ctx.json(new JSONObject()
249	                    .put("error", "INTERNAL_ERROR")
250	                    .put("message", e.getMessage())
251	                    .toString());
252	            }
253	        });
254	
255	        app.get("/reservations/{id}/document", ctx -> {
256	            try {
257	                int id = Integer.parseInt(ctx.pathParam("id"));
258	                Reservation reservation = reservationService.getReservation(id);
259	
260	                if (!reservation.isPaid()) {
261	                    ctx.status(404);
262	                    ctx.json(new JSONObject()
263	                        .put("error", "RESERVATION_NOT_FOUND")
264	                        .put("message", "Document is only available for paid reservations")
265	                        .toString());
266	                    return;
267	                }
268	
269	                Room room = getRoomRepository().findByNumber(reservation.getRoomNumber());
270	                JSONObject receiptJson = new JSONObject()
271	                    .put("title", "Comprovante de reserva")
272	                    .put("reservationId", reservation.getId())
273	                    .put("guestName", reservation.getGuestName())
274	                    .put("guestCpf", reservation.getGuestCpf())
275	                    .put("roomNumber", reservation.getRoomNumber())
276	                    .put("roomType", room.getType().getDisplayName())
277	                    .put("checkIn", reservation.getCheckIn().toString())
278	                    .put("checkOut", reservation.getCheckOut().toString())
279	                    .put("nights", reservation.getNights())
280	                    .put("subtotal", reservation.getSubtotal().doubleValue())
281	                    .put("discount", reservation.getDiscount().doubleValue())
282	                    .put("total", reservation.getTotal().doubleValue());
283	
284	                ctx.json(receiptJson.toString());
285	            } catch (ValidationException e) {
286	                ctx.status(404);
287	                ctx.json(new JSONObject()
288	                    .put("error", e.getErrorCode())
289	                    .put("message", e.getMessage())
290	                    .toString());
291	            } catch (Exception e) {
292	                ctx.status(500);
293	                ctx.json(new JSONObject()
294	                    .put("error", "INTERNAL_ERROR")
295	                    .put("message", e.getMessage())
296	                    .toString());
297	            }
298	        });
299	    }
300	
301	    private static JSONObject reservationToJson(Reservation res) {
302	        return new JSONObject()
303	            .put("id", res.getId())
304	            .put("roomNumber", res.getRoomNumber())
305	            .put("guestName", res.getGuestName())
306	            .put("guestEmail", res.getGuestEmail())
307	            .put("guestCpf", res.getGuestCpf())
308	            .put("checkIn", res.getCheckIn().toString())
309	            .put("checkOut", res.getCheckOut().toString())
310	            .put("guests", res.getGuests())
311	            .put("ratePlan", res.getRatePlan().getDisplayName())
312	            .put("nights", res.getNights())
313	            .put("subtotal", res.getSubtotal().doubleValue())
314	            .put("discount", res.getDiscount().doubleValue())
315	            .put("total", res.getTotal().doubleValue())
316	            .put("status", res.getStatus().getDisplayName())
317	            .put("amountPaid", res.getAmountPaid().doubleValue())
318	            .put("refund", res.getRefund() != null ? res.getRefund().doubleValue() : null);
319	    }
320	
321	    private static int getStatusForError(String errorCode) {
322	        return switch(errorCode) {
323	            case "ROOM_NOT_FOUND", "RESERVATION_NOT_FOUND" -> 404;
324	            case "ROOM_UNAVAILABLE", "OPERATION_NOT_ALLOWED" -> 409;
325	            case "CAPACITY_EXCEEDED" -> 422;
326	            default -> 400;
327	        };
328	    }
329	
330	    private static RoomRepository getRoomRepository() throws Exception {
331	        if (roomRepo == null) {
332	            roomRepo = new RoomRepository();
333	        }
334	        return roomRepo;
335	    }
336	}

