317	        try {
318	            List<Reservation> reservations = reservationRepo.findByMonthAndPaid(year, month);
319	            BigDecimal total = BigDecimal.ZERO;
320	            for (Reservation res : reservations) {
321	                BigDecimal tax = calculateTax(res);
322	                total = Money.add(total, tax);
323	            }
324	            return "total," + formatMoney(total);
325	        } catch (Exception e) {
326	            return "total,0.00";
327	        }
328	    }
329	
330	    private String formatRow(Reservation reservation) {
331	        BigDecimal tax = calculateTax(reservation);
332	        return reservation.getId() + "," +
333	               reservation.getRoomNumber() + "," +
334	               DateUtil.formatDateForCsv(reservation.getCheckIn()) + "," +
335	               DateUtil.formatDateForCsv(reservation.getCheckOut()) + "," +
336	               reservation.getGuests() + "," +
337	               reservation.getNights() + "," +
338	               formatMoney(tax);
339	    }
340	
341	    private BigDecimal calculateTax(Reservation reservation) {
342	        BigDecimal guestNights = new BigDecimal(reservation.getGuests() * reservation.getNights());
343	        return Money.multiply(guestNights, TAX_PER_GUEST_PER_NIGHT);
344	    }
