488	            return null;
489	        }
490	        return value.setScale(2, RoundingMode.HALF_EVEN);
491	    }
492	
493	    public static BigDecimal add(BigDecimal a, BigDecimal b) {
494	        if (a == null) a = BigDecimal.ZERO;
495	        if (b == null) b = BigDecimal.ZERO;
496	        return round(a.add(b));
497	    }
498	
499	    public static BigDecimal multiply(BigDecimal a, BigDecimal b) {
500	        if (a == null || b == null) return BigDecimal.ZERO;
501	        return round(a.multiply(b));
502	    }
503	
504	    public static BigDecimal subtract(BigDecimal a, BigDecimal b) {
505	        if (a == null) a = BigDecimal.ZERO;
506	        if (b == null) b = BigDecimal.ZERO;
507	        return round(a.subtract(b));
508	    }
509	
510	    public static BigDecimal percentage(BigDecimal value, int percent) {
511	        if (value == null) return BigDecimal.ZERO;
512	        BigDecimal percentDecimal = new BigDecimal(percent).divide(new BigDecimal(100), 10, RoundingMode.HALF_EVEN);
513	        return round(value.multiply(percentDecimal));
514	    }
